import {formatAttribute} from './attribute-format.js';
import {equipmentDisplayQuality} from './equipment-display.js';
import {renderForgeSlotPicker,forgeSlotItems} from './forge-slot-picker.js';
import {equipmentIcon} from './equipment-art.js';
import {enhancementLevel,enhancedItemBase} from './equipment-enhancement.js';
const esc=t=>String(t??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const fmt=n=>Number.isFinite(n)?String(Math.round(n*100)/100):'—';
const issues={'at-maximum':'已达到强化上限 +5','insufficient-gold':'金币不足','unavailable':'当前装备无法强化：请结束穿戴中的战斗，或先处理待确认改造。','invalid-item':'装备数据不可用','invalid-base':'基础数值不可用','stale-quote':'装备或费用已经变化，请重新预览。'};
export function renderFormalEnhancement(s,{slot=null,itemId=null,quote=null,receipt=null,error='',busy=false}={}){
 const item=s.inventory.find(it=>it.id===itemId),level=enhancementLevel(item)??0,valid=quote?.ok&&quote.itemId===itemId,bases=valid?quote.bases:{current:item?enhancedItemBase(item):null},can=!!item&&valid&&!receipt&&!busy;
 return `<section class="equipmentWorkshop formalEnhancement"><div class="workshopTitle"><div><span class="eyebrow">THE FORGE</span><h2>装备强化</h2><small>最高 +5 · 失败降一级，最低 +0</small></div></div><div class="workshopGrid"><div class="workshopOwned"><h3>选择部位</h3>${renderForgeSlotPicker(s,slot,'enhance-slot',{busy})}<h3>${slot?'选择装备':'先选择一个部位'}</h3><div class="workshopItemGrid">${forgeSlotItems(s,slot).map(it=>`<button class="workshopItem ${it.set?'setFrame':''} ${it.id===itemId?'selected':''}" data-enhance-item="${esc(it.id)}" ${busy?'disabled':''} aria-pressed="${it.id===itemId}" title="${esc(it.name)}">${equipmentIcon(it,{size:32})}${Object.values(s.equip).includes(it.id)?'<span class="equippedDot">E</span>':''}<b>+${enhancementLevel(it)??0}</b></button>`).join('')}</div></div><div class="workshopBench">${item?`<div class="workshopItemHeading"><span class="workshopBigIcon">${equipmentIcon(item,{size:64})}</span><div><h3 class="r${equipmentDisplayQuality(item)}text">${esc(item.name)} +${level}${item.divine?'<small class="divineBadge">神赐</small>':''}</h3><small>Lv.${item.level}</small></div></div><div class="workshopBasePreview"><table><thead><tr><th>基础属性</th><th>当前 +${level}</th><th>成功 +${Math.min(5,level+1)}</th><th>失败 +${Math.max(0,level-1)}</th></tr></thead><tbody>${[['atk','攻击'],['armor','护甲'],['hp','生命']].map(([key,name])=>`<tr><th>${name}</th><td>${formatAttribute(bases.current?.[key])}</td><td class="workshopGain">${formatAttribute(bases.success?.[key])}</td><td>${formatAttribute(bases.failure?.[key])}</td></tr>`).join('')}</tbody></table></div><p class="workshopSmall">仅提升原始基础属性；普通词条、特殊词条、套装与神赐比例不变。预览为取整后的基础属性；神赐仍按原比例单独计算。${item.bless?`旧制强化 +${item.bless} 保留，独立计算。`:''}</p><div class="workshopQuote"><div><small>本次 +${level} → +${Math.min(5,level+1)}</small><strong>${valid?fmt(quote.cost.gold)+' 金币':'—'}</strong></div><div><small>成功机会</small><strong>${valid?(Number.isFinite(quote.baseSuccessRate)?fmt(quote.successRate*100):Math.round(quote.successRate*100))+'%':'—'}</strong>${valid&&Number.isFinite(quote.baseSuccessRate)?`<small class="enhancementRateBreakdown">基础 ${fmt(quote.baseSuccessRate*100)}% · ${quote.successRate>quote.baseSuccessRate?'祖炉眷顾后':'实际'} ${fmt(quote.successRate*100)}%</small>`:''}</div></div><button class="primary workshopEnhance" data-enhance-attempt="${esc(item.id)}" ${can?'':'disabled'}>${level===5?'已达到 +5':'支付并尝试强化'}</button><p class="workshopSmall">费用由装备等级、品质和目标强化等级决定。成功或失败均扣本次费用；失败会降低1级，最低 +0。下一次费用随强化等级变化。</p>`:'<p>先选择部位，再选择一件已有装备。</p>'}${receipt?`<div class="workshopResult ${receipt.success?'isSuccess':'isFailure'}" role="status"><strong>${receipt.success?'强化成功':'强化失败'} · +${receipt.fromLevel} → +${receipt.toLevel}</strong><small>已扣 ${receipt.cost.gold} 金币</small><button data-enhance-continue="1">继续强化</button></div>`:''}${error||quote?.ok===false?`<p class="workshopError" role="alert">${esc(error||issues[quote.reason]||'暂时无法强化')}</p>`:''}${quote?.ok===false||error?'<button data-enhance-refresh="1">重新预览</button>':''}</div></div></section>`;
}
